mapper.select:

/*selectMasterMpRqMyAgentGroupAgentList*/
	WITH A AS (
		SELECT D.CODE2 AS AGENT
		     , D.VALUE1 AS SEQ
		  FROM ICOMCOD3 D
		 WHERE D.BUYER = 'KRKORE0001'
		   AND D.TYPE = 'MYAGGRPD'
		   AND D.CODE1 = #{GROUP_CODE}
		   AND D.ADD_USER_ID = #{st_user_id}
	)



	 ORDER BY A.SEQ, C.COM_NAME_LOC


/*selectMasterMpRqMyAgentGroupCnt*/
	SELECT COUNT(*)
	  FROM ICOMCOD3
	 WHERE BUYER = 'KRKORE0001'
	   AND TYPE = 'MYAGGRP'
	   AND CODE1 = #{st_user_id}


/*selectMasterMpRqMyAgentGroupOwnCnt*/
	SELECT COUNT(*)
	  FROM ICOMCOD3
	 WHERE BUYER = 'KRKORE0001'
	   AND TYPE = 'MYAGGRP'
	   AND CODE1 = #{st_user_id}
	   AND CODE2 = #{GROUP_CODE}


/*selectMasterMpRqMyAgentGroupCodeByName*/
	SELECT MIN(CODE2)
	  FROM ICOMCOD3
	 WHERE BUYER = 'KRKORE0001'
	   AND TYPE = 'MYAGGRP'
	   AND CODE1 = #{st_user_id}
	   AND TEXT1 = #{GROUP_NAME}


/*selectMasterMpRqMyAgentGroupAgentCodeList*/
	SELECT CODE2
	  FROM ICOMCOD3
	 WHERE BUYER = 'KRKORE0001'
	   AND TYPE = 'MYAGGRPD'
	   AND CODE1 = #{GROUP_CODE}
	   AND ADD_USER_ID = #{st_user_id}
	 ORDER BY VALUE1

mapper.update:

/*insertMasterMpRqMyAgentGroup*/
	INSERT INTO ICOMCOD3 (BUYER, TYPE, CODE1, CODE2, TEXT1, FLAG, ADD_USER_ID, ADD_DATE)
	VALUES ('KRKORE0001', 'MYAGGRP', #{st_user_id}, #{GROUP_CODE}, #{GROUP_NAME}, 'Y', #{st_user_id}, TO_CHAR(SYSDATE, 'YYYYMMDD'))


/*deleteMasterMpRqMyAgentGroupAgentAll*/
	DELETE FROM ICOMCOD3
	 WHERE BUYER = 'KRKORE0001'
	   AND TYPE = 'MYAGGRPD'
	   AND CODE1 = #{GROUP_CODE}
	   AND ADD_USER_ID = #{st_user_id}


/*deleteMasterMpRqMyAgentGroup*/
	DELETE FROM ICOMCOD3
	 WHERE BUYER = 'KRKORE0001'
	   AND TYPE = 'MYAGGRP'
	   AND CODE1 = #{st_user_id}
	   AND CODE2 = #{GROUP_CODE}
